import { redisClient } from "../config/redis.js";
import { otpHashing } from "../utils/mail.js";


const OTP_EXPIRY = 5 * 60; // 5 minutes
const OTP_MAX_ATTEMPTS = 5;
const OTP_RESEND_COOLDOWN = 60; // 60 seconds


const getOTPKey = (email) => {
    return `ql:otp:registration:${email.toLowerCase()}`;
};

const getAttemptKey = (email) => {
    return `ql:otp:attempts:registration:${email.toLowerCase()}`;
};

const getCooldownKey = (email) => {
    return `ql:otp:cooldown:registration:${email.toLowerCase()}`;
};


/**
 * Store the OTP generated by the auth controller
 */
const storeOTP = async (email, otp) => {
    const normalizedEmail = email.toLowerCase();

    const otpKey = getOTPKey(normalizedEmail);
    const attemptKey = getAttemptKey(normalizedEmail);
    const cooldownKey = getCooldownKey(normalizedEmail);

    // Check resend cooldown
    const cooldownExists = await redisClient.exists(cooldownKey);

    if (cooldownExists) {
        const remainingTime = await redisClient.ttl(cooldownKey);

        return {
            success: false,
            reason: "OTP_COOLDOWN",
            remainingTime
        };
    }

    // Hash OTP before storing it
    const otpHash = otpHashing(otp);

    // Store hashed OTP for 5 minutes
    await redisClient.set(
        otpKey,
        otpHash,
        {
            EX: OTP_EXPIRY
        }
    );

    // Reset OTP attempts
    await redisClient.set(
        attemptKey,
        "0",
        {
            EX: OTP_EXPIRY
        }
    );

    // Set resend cooldown
    await redisClient.set(
        cooldownKey,
        "1",
        {
            EX: OTP_RESEND_COOLDOWN
        }
    );

    return {
        success: true
    };
};


/**
 * Verify OTP entered by the user
 */
const verifyOTP = async (email, otp) => {
    const normalizedEmail = email.toLowerCase();

    const otpKey = getOTPKey(normalizedEmail);
    const attemptKey = getAttemptKey(normalizedEmail);

    // Get stored OTP hash
    const storedHash = await redisClient.get(otpKey);

    // OTP does not exist or has expired
    if (!storedHash) {
        return {
            success: false,
            reason: "OTP_EXPIRED"
        };
    }

    // Get current attempt count
    const attempts = Number(
        await redisClient.get(attemptKey) || 0
    );

    // Maximum attempts already reached
    if (attempts >= OTP_MAX_ATTEMPTS) {
        await redisClient.del(otpKey);

        return {
            success: false,
            reason: "MAX_ATTEMPTS"
        };
    }

    // Hash the OTP provided by the user
    const providedHash = otpHashing(otp);

    // Compare hashes
    if (providedHash !== storedHash) {

        const newAttempts = await redisClient.incr(attemptKey);

        if (newAttempts >= OTP_MAX_ATTEMPTS) {
            await redisClient.del(otpKey);

            return {
                success: false,
                reason: "MAX_ATTEMPTS"
            };
        }

        return {
            success: false,
            reason: "INVALID_OTP",
            attemptsLeft: OTP_MAX_ATTEMPTS - newAttempts
        };
    }

    // OTP is valid
    await redisClient.del(otpKey);
    await redisClient.del(attemptKey);

    return {
        success: true
    };
};


export { storeOTP,verifyOTP };